export const ffmpeg = process.env.FFMPEG_PATH || "ffmpeg";
export const ffprobe = process.env.FFPROBE_PATH || "ffprobe";
export function mediaEnvironment():Record<string,string>&{NODE_ENV:"development"|"production"|"test"}{return {...Object.fromEntries(Object.entries(process.env).filter((entry):entry is [string,string]=>typeof entry[1]==="string"&&!/KEY|TOKEN|SECRET|PASSWORD|DATABASE_URL/i.test(entry[0]))),NODE_ENV:process.env.NODE_ENV||"production"};}
const activeChildren=new Set<ReturnType<typeof spawn>>();
export function cancelCommands(){for(const child of activeChildren)child.kill("SIGKILL");}
export async function command(binary: string, args: string[], timeout = 180_000): Promise<string> {
  return new Promise((done,reject) => {
    const child = spawn(binary,args,{shell:false,windowsHide:true,stdio:["ignore","pipe","pipe"],env:mediaEnvironment()});
    activeChildren.add(child);
    let text = "", settled = false;
    const timer = setTimeout(() => { child.kill("SIGKILL"); reject(new Error(`${binary} exceeded its time limit`)); },timeout);
    const collect = (data: Buffer) => { text = (text + data.toString()).slice(-2_000_000); };
    child.stdout.on("data",collect); child.stderr.on("data",collect);
    child.on("error", error => { activeChildren.delete(child); if (!settled) { settled=true; clearTimeout(timer); reject(error); } });
    child.on("close", code => { activeChildren.delete(child); if (!settled) { settled=true; clearTimeout(timer); if(code === 0) done(text); else reject(new Error(`${binary} failed (${code}): ${text.slice(-5000)}`)); } });
  });
}
export async function writeJson(path: string, data: unknown) { await mkdir(dirname(path),{recursive:true}); await writeFile(path, JSON.stringify(data,null,2)); }
export async function json<T>(path: string): Promise<T> { return JSON.parse(await readFile(path,"utf8")) as T; }
export async function hash(path: string) { return createHash("sha256").update(await readFile(path)).digest("hex"); }
export async function probe(path: string) {
  const data = JSON.parse(await command(ffprobe,["-v","error","-show_streams","-show_format","-of","json",path]));
  const video = data.streams?.find((s: {codec_type:string}) => s.codec_type === "video");
  const audio = data.streams?.find((s: {codec_type:string}) => s.codec_type === "audio");
  return { raw:data, video, audio, width: Number(video?.width || 0), height:Number(video?.height || 0), duration:Number(data.format?.duration || video?.duration || 0) };
}
export async function frame(path: string, out: string, at: number, maxWidth=1600) {
  await mkdir(dirname(out),{recursive:true});
  await rm(out,{force:true});
  await command(ffmpeg,["-v","error","-y","-ss",String(Math.max(0,at)),"-i",path,"-frames:v","1","-vf",`scale='min(${maxWidth},iw)':-2`,"-q:v","2",out]);
  await requireFrame(out);
}
async function requireFrame(out:string) {
  if(!(await stat(out).catch(()=>null))?.size)throw new Error(`FFmpeg did not decode the requested frame: ${out}`);
}
/** Decode by ordinal, avoiding fractional concat timestamps at the final frame. */
export async function frameIndex(path:string,out:string,index:number,maxWidth=1600) {
  if(!Number.isInteger(index)||index<0)throw new Error("Frame index must be a nonnegative integer");
  await mkdir(dirname(out),{recursive:true});await rm(out,{force:true});
  await command(ffmpeg,["-v","error","-y","-i",path,"-vf",`select=eq(n\\,${index}),scale='min(${maxWidth},iw)':-2`,"-frames:v","1","-fps_mode","vfr","-q:v","2",out]);
  await requireFrame(out);
}
export async function audioMeasurements(path: string) {
  const raw = await command(ffmpeg,["-hide_banner","-i",path,"-vn","-af","loudnorm=I=-14:TP=-1:LRA=11:print_format=json,silencedetect=n=-45dB:d=1","-f","null","-"],180_000);
  const match = raw.match(/\{\s*"input_i"[\s\S]*?\}/);
  return { loudness:match ? JSON.parse(match[0]) : null, silence:raw.split(/\r?\n/).filter(x => x.includes("silence_start") || x.includes("silence_end")) };
}
export async function doctor(workspace: string, skillRoot: string) {
  const versions: Record<string,string> = {node:process.version,renderer:MOTION_RENDERER_VERSION};
  for(const name of ["hyperframes","gsap"]) versions[name]=JSON.parse(await readFile(join(process.cwd(),"node_modules",name,"package.json"),"utf8")).version;
  versions.ffmpeg=(await command(ffmpeg,["-version"])).split(/\r?\n/)[0];
  versions.ffprobe=(await command(ffprobe,["-version"])).split(/\r?\n/)[0];
  const output = await command(process.env.PYTHON_PATH || "python3",["-X","utf8",join(skillRoot,"scripts","video_tool.py"),"doctor"]);
  if(JSON.parse(output).ok!==true)throw new Error("The pinned skill media doctor did not pass");
  await writeFile(join(workspace,"analysis","doctor.txt"),output);
  return versions;
}

/** Provider grammar handles shape only; the production compiler still checks all source bindings and limits. */
type Schema = Record<string, unknown>;
export interface ScriptConstraints { assetIds: string[]; roleEvidenceIds: Record<string, string[]>; selectedFactIds: string[]; uiDocuments?: { id: string; elementIds: string[]; editableElementIds: string[]; stateIds: string[]; capabilityFactIds: string[] }[] }
const text = { type: "string" };
const choice = (...values: string[]) => ({ type: "string", enum: values });
const object = (properties: Record<string, Schema>, optional: string[] = []): Schema => ({ type: "object", properties, required: Object.keys(properties).filter(key => !optional.includes(key)), additionalProperties: false });
const array = (items: Schema) => ({ type: "array", items });
const visual = { anyOf: [
  object({ kind: choice("showcase") }),
  object({ kind: choice("focus"), regionId: text }),
  object({ kind: choice("panels"), secondaryAssetId: text, secondaryEvidenceId: text }),
  object({ kind: choice("connections"), nodes: array(object({ label: text, evidenceId: text })) }),
] };
export const SCRIPT_OUTPUT_SCHEMA = object({
  sufficientEvidence: { type: "boolean" }, reason: text, product: text, summary: text,
  accent: { type: "string", description: "A six digit #RRGGBB color." }, background: choice("light", "dark"),
  musicPrompt: text, sfxPrompt: text, assumptions: array(text),
  scenes: array(object({
    storyRole: choice("problem", "product", "mechanism", "outcome", "differentiator", "cta"),
    assetId: { type: "string", description: "An actual selected source asset ID, including for typography-only scenes. Never null." },
    headline: text, detail: { type: "string", description: "Use an empty string when no detail is needed, never null." },
    evidenceId: text, durationSeconds: { type: "number" }, sourceInSeconds: { type: "number", description: "Use zero for still images." },
    preserveAudio: { type: "boolean" }, purpose: text, referenceTechnique: text,
    presentation: object({ template: choice("hook", "brand", "proof", "features", "offer", "cta"), theme: choice("light", "dark"), transition: choice("cut", "iris", "lift", "expand"), cards: array(object({ title: text, body: text, evidenceId: text })), visual }, ["cards", "visual"]),
  }, ["storyRole"])),
});
/** Only models with verified direct structured-output support use this transport option. */
export function scriptOutputConfig(model: string, direct: boolean, policy?: string, constraints?: ScriptConstraints) {
  if (!direct || !["script-v1", "ui-design-v1"].includes(policy || "") || !/^claude-(?:sonnet-4-6|opus-4-6)(?:-|$)/.test(model)) return undefined;
  return { format: { type: "json_schema", schema: policy === "ui-design-v1" ? UI_OUTPUT_SCHEMA : constraints ? constrainedScriptSchema(constraints) : SCRIPT_OUTPUT_SCHEMA } };
}

/** Bind narrative choices in the grammar, before the semantic compiler checks actual claims. */
export function constrainedScriptSchema(constraints: ScriptConstraints): Schema {
  const schema = structuredClone(SCRIPT_OUTPUT_SCHEMA) as any;
  const scene = schema.properties.scenes.items, presentation = scene.properties.presentation;
  if (!constraints.assetIds.length || !constraints.selectedFactIds.length) throw new Error("Script grammar requires verified source IDs");
  scene.properties.assetId = choice(...constraints.assetIds);
  presentation.properties.cards.items.properties.evidenceId = choice(...constraints.selectedFactIds);
  presentation.properties.visual.anyOf[2].properties.secondaryAssetId = choice(...constraints.assetIds);
  presentation.properties.visual.anyOf[2].properties.secondaryEvidenceId = choice(...constraints.selectedFactIds);
  presentation.properties.visual.anyOf[3].properties.nodes.items.properties.evidenceId = choice(...constraints.selectedFactIds);
  const uiVariants = constraints.uiDocuments?.map(document => {
    if (!document.elementIds.length || !document.stateIds.length || !document.capabilityFactIds.length) throw new Error("UI script grammar requires documented element/state/capability IDs");
    const timed = { atFrame: { type: "integer", description: "Start at or after frame 30, in sequential non-overlapping order." }, durationFrames: { type: "integer", description: "Positive duration in frames: click at least 6, type at least 12, other actions at least 1." }, evidenceId: choice(...document.capabilityFactIds) };
    const actions = [
      ...["pointer", "click", "select"].map(kind => object({ kind: choice(kind), ...timed, targetId: choice(...document.elementIds) })),
      ...(document.editableElementIds.length ? [object({ kind: choice("type"), ...timed, targetId: choice(...document.editableElementIds), text: { type: "string", description: "Illustrative input, at most 160 characters; prefer six words or fewer." } })] : []),
      object({ kind: choice("state"), ...timed, stateId: choice(...document.stateIds) }),
    ];
    return object({ kind: choice("ui-demo"), documentId: choice(document.id), actions: array({ anyOf: actions }) });
  });
  if (uiVariants?.length) presentation.properties.visual.anyOf.push(...uiVariants);
  // Reuse one presentation definition to keep grammar size and optional-key counts bounded.
  schema.$defs = { presentation };
  if (uiVariants?.length) {
    const uiPresentation = structuredClone(presentation);
    uiPresentation.properties.template = choice("proof");
    uiPresentation.properties.visual = { anyOf: uiVariants };
    delete uiPresentation.properties.cards;
    uiPresentation.required = [...uiPresentation.required, "visual"];
    schema.$defs.uiPresentation = uiPresentation;
  }
  scene.properties.presentation = { $ref: "#/$defs/presentation" };
  const roles = ["problem", "product", "mechanism", "outcome", "differentiator", "cta"];
  const variants = roles.filter(role => constraints.roleEvidenceIds[role]?.length).map(role => ({
    ...scene, required: [...scene.required, "storyRole"],
    properties: { ...scene.properties, storyRole: choice(role), evidenceId: choice(...constraints.roleEvidenceIds[role]), ...(role === "mechanism" && uiVariants?.length ? { presentation: { $ref: "#/$defs/uiPresentation" } } : {}) },
  }));
  if (!["mechanism", "outcome", "cta"].every(role => constraints.roleEvidenceIds[role]?.length)) throw new Error("Script grammar requires verified story roles");
  schema.properties.scenes.items = { anyOf: variants };
  return schema;
}

const rect = object({ x: { type: "number" }, y: { type: "number" }, width: { type: "number" }, height: { type: "number" } });
const ids = array(text), basis = choice("source-ui", "example-content");
/** Shape grammar only: source fidelity, references, finite bounds and payload limits remain compiler checks. */
export const UI_OUTPUT_SCHEMA = object({
  sufficientEvidence: { type: "boolean" }, reason: text,
  documents: array(object({
    id: text, sourceAssetIds: ids, capabilityFactIds: ids, viewport: object({ width: { type: "integer" }, height: { type: "integer" } }),
    styles: array(object({ id: text, fill: text, color: text, borderColor: text, fontSize: { type: "number" }, fontWeight: { type: "integer" }, radius: { type: "number" } })),
    elements: array(object({ id: text, type: choice("panel", "text", "button", "input", "textarea", "tab", "list-item", "icon", "node", "edge"), rect, styleId: text, text, textBasis: basis, sourceAssetId: text, sourceRect: rect, initiallyVisible: { type: "boolean" }, fromId: text, toId: text }, ["fromId", "toId"])),
    states: array(object({ id: text, basis: choice("observed", "illustrative"), sourceAssetId: text, evidenceIds: ids, visibleElementIds: ids, selectedElementIds: ids, textValues: array(object({ elementId: text, text, textBasis: basis })) }, ["sourceAssetId"])),
  })),
});

/** Parse one complete JSON document; a sole fenced document may have prose before it. */
export function parseModelJson(raw: string): unknown {
  const text=raw.trim();
  try{return JSON.parse(text);}catch{}
  // No substring/bracket guessing, multiple alternatives or incomplete blocks.
  // Outside prose is discarded as commentary, never promoted to source evidence.
  const fences=[...text.matchAll(/```/g)];
  if(fences.length!==2)throw new Error("Expected one complete JSON response");
  let prefixIsJson=false;
  try { JSON.parse(text.slice(0,fences[0].index).trim()); prefixIsJson=true; } catch {}
  if(prefixIsJson)throw new Error("Multiple JSON responses are ambiguous");
  const block=text.slice(fences[0].index).match(/^```(?:json)?[ \t]*\r?\n([\s\S]*?)\r?\n```$/i);
  if(!block)throw new Error("Expected one complete fenced JSON response");
  return JSON.parse(block[1]);
}

import type { Plan, Presentation, Scene } from "./types";

/** One renderer contract shared by composition, source checks, QC and reservations. */
export function resolvePresentation(scene:Scene,plan:Pick<Plan,"background">):Presentation {
 const value=scene.presentation||{template:"proof",theme:plan.background,transition:"cut"};
 if(!["hook","brand","proof","features","offer","cta"].includes(value.template)||!["light","dark"].includes(value.theme)||!["cut","iris","lift","expand"].includes(value.transition)||(value.cards?.length||0)>3)throw new Error("Unsupported motion presentation");
 if(scene.preserve_audio)return {...value,template:"proof",transition:"cut",cards:undefined,visual:undefined};
 const visual=value.visual;
 if(visual){
  if(visual.kind==="connections"){
   if(value.template!=="features"||value.cards?.length||visual.nodes.length<2||visual.nodes.length>3||visual.nodes.some(node=>!node.label.trim()||!node.evidenceId))throw new Error("Unsupported explanatory connection graphic");
  }else if(value.template!=="proof"||!["showcase","focus","panels","ui-demo"].includes(visual.kind))throw new Error("A product treatment requires a proof scene");
  if(visual.kind==="focus"){
   const r=visual.region;
   if(!visual.regionId||!r||Object.values(r).some(v=>!Number.isFinite(v))||r.x<0||r.y<0||r.width<=0||r.height<=0||r.x+r.width>1.000001||r.y+r.height>1.000001)throw new Error("Focus region must be compiled from bounded source evidence");
  }
  if(visual.kind==="panels"&&(!visual.secondaryAssetId||!visual.secondaryEvidenceId))throw new Error("A second proof panel needs source and fact bindings");
 }
 return value;
}

export function motionUsage(scene:Scene,plan:Pick<Plan,"background"|"brand"|"uiDocuments">){
 const presentation=resolvePresentation(scene,plan),visual=presentation.visual;
 const uiDocumentId=visual?.kind==="ui-demo"?visual.documentId:null,document=uiDocumentId?plan.uiDocuments?.find(document=>document.id===uiDocumentId):undefined;
 if(uiDocumentId&&!document)throw new Error("A UI demonstration needs a compiled source-bound document");
 const reconstructionSourceAssetIds=document?.sourceAssetIds||[];
 const proofAssetIds=presentation.template==="proof"&&!uiDocumentId?[scene.asset_id,...(visual?.kind==="panels"?[visual.secondaryAssetId]:[])]:[];
 const logoAssetId=["brand","cta"].includes(presentation.template)?plan.brand?.logoAssetId||null:null;
 const visibleAssetIds=[...new Set([...proofAssetIds,...(logoAssetId?[logoAssetId]:[])])];
 return {presentation,proofAssetIds,logoAssetId,visibleAssetIds,reconstructionSourceAssetIds,uiDocumentId,copiedAssetIds:[...new Set([scene.asset_id,...visibleAssetIds,...reconstructionSourceAssetIds])],extraCopy:visual?.kind==="connections"?visual.nodes.map(node=>node.label):[]};
}

export const motionAssetIds=(plan:Pick<Plan,"scenes"|"background"|"brand"|"uiDocuments">)=>[...new Set(plan.scenes.flatMap(scene=>motionUsage(scene,plan).copiedAssetIds))];

